import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CZo9GF0W.js";const g=JSON.parse('{"title":"The conformance kit","description":"","frontmatter":{},"headers":[],"relativePath":"drivers/conformance.md","filePath":"drivers/conformance.md","lastUpdated":1789060268000}'),n={name:"drivers/conformance.md"};function r(o,e,d,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="the-conformance-kit" tabindex="-1">The conformance kit <a class="header-anchor" href="#the-conformance-kit" aria-label="Permalink to &quot;The conformance kit&quot;">​</a></h1><p><code>packages/core/test/driverConformance.ts</code> is the suite every driver must pass.</p><p><strong>A driver is called <em>supported</em> only when this runs green against a real server in CI.</strong> There are no aspirational drivers, and &quot;it mostly works&quot; is not a state this project has a word for.</p><h2 id="the-rule-that-shapes-it" tabindex="-1">The rule that shapes it <a class="header-anchor" href="#the-rule-that-shapes-it" aria-label="Permalink to &quot;The rule that shapes it&quot;">​</a></h2><p>Every check is gated on a <strong>capability flag</strong>, never on the driver&#39;s identity. The kit describes the contract; an engine that cannot do something declares so and is not asked to.</p><blockquote><p>If a check here ever needs to know which engine it is talking to, the contract is wrong.</p></blockquote><p>That is a real instruction, not a slogan. Finding a case where the kit would need to branch on <code>driver.id</code> is a finding about the abstraction, and it gets filed as one.</p><p>The kit also writes <strong>no statement of its own</strong>. It asks your fixture to create a container and put records in it, and asks your <em>adapter</em> to build everything else. That is what lets a document store and a key-value store run the same assertions as PostgreSQL rather than being handed SQL they cannot parse.</p><h2 id="wiring-it-up" tabindex="-1">Wiring it up <a class="header-anchor" href="#wiring-it-up" aria-label="Permalink to &quot;Wiring it up&quot;">​</a></h2><p>A relational engine describes a dialect and gets a fixture for free:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { runDriverConformance, sqlEngineFixture } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;../../core/test/driverConformance.js&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { acmeDriver } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;../src/index.js&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runDriverConformance</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;acme&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  adapter: acmeDriver,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  open</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> connectForTest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fixture: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sqlEngineFixture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(acmeDriver, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ACME_DIALECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  available: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Boolean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ACME_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p><code>available: false</code> skips the suite rather than failing it, so a contributor without that server running still gets a green local run — and CI, where the server <em>is</em> running, does not.</p><h2 id="writing-an-enginefixture" tabindex="-1">Writing an <code>EngineFixture</code> <a class="header-anchor" href="#writing-an-enginefixture" aria-label="Permalink to &quot;Writing an \`EngineFixture\`&quot;">​</a></h2><p>Anything not relational writes the fixture directly. It is the whole engine-specific half of the kit:</p><table tabindex="0"><thead><tr><th>Member</th><th>What it is</th></tr></thead><tbody><tr><td><code>ref</code></td><td>The container, as your driver names it</td></tr><tr><td><code>fields</code></td><td>Field metadata, as <code>buildSelect</code>/<code>buildDml</code> take it</td></tr><tr><td><code>keyField</code></td><td>The field an edit addresses a record by</td></tr><tr><td><code>labelField</code></td><td>A short text field the round-trip checks read back</td></tr><tr><td><code>seed</code></td><td>Records <code>create</code> writes, so paging has something to find</td></tr><tr><td><code>create</code> / <code>drop</code> / <code>read</code></td><td>Make, remove, and read the container the engine&#39;s own way</td></tr><tr><td><code>run?</code></td><td>Runs a statement your adapter built. Defaults to <code>session.queryAll(text, params)</code>, which is right wherever the statement text <em>is</em> the wire form. Override it if your command document rides in <code>params</code>.</td></tr><tr><td><code>ping</code></td><td>The simplest possible round trip</td></tr><tr><td><code>failing</code></td><td>Something the engine refuses, for the error-shape check</td></tr><tr><td><code>nullAndEmpty?</code></td><td>One row of exactly <code>[null, &#39;&#39;]</code>, where the engine has both</td></tr><tr><td><code>largeInteger?</code></td><td>An integer at or near the 64-bit limit, and its exact string</td></tr><tr><td><code>exactDecimal?</code></td><td>A value the engine represents exactly and JavaScript cannot</td></tr><tr><td><code>echo?</code></td><td>Returns the value it was given, for parameter binding</td></tr><tr><td><code>awkwardIdentifier?</code></td><td>An identifier needing quoting, created by <code>create</code></td></tr><tr><td><code>heterogeneous?</code></td><td>Records with fields the seeded ones lack (schemaless engines)</td></tr><tr><td><code>unknownCommand?</code></td><td>A command your classifier cannot place at all</td></tr><tr><td><code>failingEdit?</code></td><td>An edit that must fail on apply, for the partial-apply report</td></tr></tbody></table><p>The optional members are the honest ones: an engine with no exact decimal type omits <code>exactDecimal</code> and the check does not run. Omitting one you <em>do</em> have is the only way to pass a check your driver does not satisfy — and you would be doing it in your own package, in a file a reviewer is looking at.</p><h2 id="what-it-checks" tabindex="-1">What it checks <a class="header-anchor" href="#what-it-checks" aria-label="Permalink to &quot;What it checks&quot;">​</a></h2><p><strong>Session.</strong> Server information is reported. <code>ping</code> answers. Rows come back as positional arrays with field metadata. A command tag is reported. A failure surfaces as a <code>PittaError</code> with a code, rather than as whatever the client library threw.</p><p><strong>Values.</strong> Null and empty string stay distinct. A 64-bit integer round-trips as an exact string. An exact decimal round-trips exactly. A bound parameter comes back as itself.</p><p><strong>Paging and streaming.</strong> <code>fetch()</code> pages. <code>rows()</code> iterates. Neither buffers the whole result to satisfy the other.</p><p><strong>Transactions.</strong> A rollback leaves no trace — gated on <code>supportsTransactions</code>, so an engine without them is not asked to pretend.</p><p><strong>Identifiers.</strong> <code>quoteIdent</code> handles an identifier that needs quoting and escapes an embedded quote character.</p><p><strong>Statement building.</strong> <code>buildSelect</code> produces something that runs. It rejects a column that is not in the field list. <code>buildDml</code> produces edits that run and are visible afterwards, and refuses an update with no key columns.</p><p><strong>Introspection.</strong> A root level is declared, every declared child kind has a definition, and every supported level runs without error against the fixture schema.</p><p><strong>Capability honesty.</strong> This is the section that catches the interesting bugs:</p><ul><li>Schemas appear in the introspection plan only if <code>supportsSchemas</code>.</li><li>A row-id column exists only if <code>supportsRowIdFallback</code>.</li><li><code>generateDdl</code> and <code>diffSchema</code> are present only if their flags are.</li><li>Generated placeholders match the declared <code>parameterStyle</code>.</li><li>At least one producible <code>resultShape</code> is declared.</li><li>The declared language&#39;s extensions are usable as file suffixes.</li><li>Paging works the way the paging flags say it does.</li></ul><p><strong>Multi-model.</strong> Four checks only a non-relational engine can fail:</p><ol><li><strong>Stable document projection.</strong> The same columns in the same order across two reads, unioned across every sampled record rather than taken from whichever one came first. A projection that reshuffles between reads is a grid whose columns move under the cursor.</li><li><strong>Missing survives the round trip as missing.</strong> At least one cell is absent rather than null, and a record that <em>does</em> carry the field with a null value still reads as null. The two stay tellable apart end to end (ADR-039).</li><li><strong>An unknown command is refused on <code>prod</code>.</strong> Nothing can say what it does, so production asks — by making the user type the connection name (ADR-040).</li><li><strong>A non-atomic batch reports exactly which edits were applied.</strong> The promise made by <code>supportsAtomicEdits: false</code>: the batch stops, earlier edits stand, and the caller knows which those were (ADR-041). One edit is not always one statement, and the report tracks that.</li></ol><h2 id="the-echo-driver" tabindex="-1">The echo driver <a class="header-anchor" href="#the-echo-driver" aria-label="Permalink to &quot;The echo driver&quot;">​</a></h2><p><code>test/echo-driver</code> is a deliberately non-relational engine — a different language, imperative introspection, document results, no transactions — that the kit runs against on <strong>every commit</strong>, with no server needed.</p><p>It exists so that a contract change which quietly assumes SQL fails immediately, in a unit test, rather than in the next real driver somebody writes. If you are changing <code>core</code>, that is the test that tells you whether the change was as generic as you thought.</p><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # unit tests, including SQLite and the echo driver</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:up</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # every engine, seeded, in Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # the kit against real servers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db:down</span></span></code></pre></div><p><code>docker-compose.test.yml</code> runs PostgreSQL 13/15/17, MySQL 8, MariaDB 11, SQL Server 2022, MongoDB (standalone and a replica set), and Redis (6.2, 7, Stack, and a cluster). Add your engine there and wire the suite into CI in the same PR as the driver.</p>`,34)])])}const k=t(n,[["render",r]]);export{g as __pageData,k as default};
